/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METPrintMgmtReportFormatPopulatorAppSuite_Extension</c> populates the PrintMgmtReportFormat table used for print management 
/// with the documents.
/// </summary>
[ExtensionOf(classStr(PrintMgmtReportFormatPopulator))]
public final class METPrintMgmtReportFormatPopulatorAppSuite_Extension
{
    #ISOCountryRegionCodes
    #PrintMgmtSetup

}

Method.Source:
    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// adds documents
    /// </summary>
    protected void addDocuments()
    {
        //this.addStandard(PrintMgmtDocumentType::METCustActivityStatement);
        this.customAddSalesDocuments();

        // 17952
        this.addOther(
            PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, 
            ssrsReportStr(METPurchPurchaseOrder, Report), 
            ssrsReportStr(METPurchPurchaseOrder, Report),
            #NoCountryRegionId);

        // 17952
        this.addOther(
            PrintMgmtDocumentType::PurchaseOrderRequisition,
            ssrsReportStr(METPurchPurchaseOrder, Report),
            ssrsReportStr(METPurchPurchaseOrder, Report),
            #NoCountryRegionId);

        // 17952
        this.addOther(
            PrintMgmtDocumentType::SalesOrderInvoice,
            ssrsReportStr(METSalesInvoice, Report),
            ssrsReportStr(METSalesInvoice, Report),
            #NoCountryRegionId);
    
        // 17952
        this.addOther(
            PrintMgmtDocumentType::SalesFreeTextInvoice,
            ssrsReportStr(METFreeTextInvoice, Report),
            ssrsReportStr(METFreeTextInvoice, Report),
            #NoCountryRegionId);

        next addDocuments();
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// Adds sales records to the PrintMgmtReportFormat table.
    /// </summary>
    private void customAddSalesDocuments()
    {
        //this.addStandard(PrintMgmtDocumentType::METCustActivityStatement, #NoCountryRegionId);
        //this.addOther(PrintMgmtDocumentType::METCustActivityStatement, ssrsReportStr(METCustActivityStatement, Report), ssrsReportStr(METCustActivityStatement, Report), #NoCountryRegionId);

        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::METCustActivityStatement, ssrsReportStr(METCustActivityStatement, Report), ssrsReportStr(METCustActivityStatement, Report), #NoCountryRegionId, true);
    }
